// Driving time: most hill drives are plains highway first, then slower hill roads
function route_drive_hours($km, $is_hill) { return $km / ($is_hill ? 44 : 55); }
function route_travel_time($km, $is_hill) {
    $lo = max(1, (int) floor(route_drive_hours($km, $is_hill)));
    return $lo . '-' . ($lo + ($lo < 6 ? 1 : 2)) . ' hrs';
}
